import{_ as e,c as r,o as t,ae as i}from"./chunks/framework.CDjunVez.js";const _=JSON.parse('{"title":"常见问题（FAQ）","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md","lastUpdated":1766459798000}'),o={name:"faq.md"};function l(h,a,n,d,s,c){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="常见问题-faq" tabindex="-1">常见问题（FAQ） <a class="header-anchor" href="#常见问题-faq" aria-label="Permalink to &quot;常见问题（FAQ）&quot;">​</a></h1><h2 id="预警可见性与分配" tabindex="-1">预警可见性与分配 <a class="header-anchor" href="#预警可见性与分配" aria-label="Permalink to &quot;预警可见性与分配&quot;">​</a></h2><h3 id="_1-为什么我在首页看不到某条预警" tabindex="-1">1.为什么我在首页看不到某条预警？ <a class="header-anchor" href="#_1-为什么我在首页看不到某条预警" aria-label="Permalink to &quot;1.为什么我在首页看不到某条预警？&quot;">​</a></h3><p>该预警未分配给您。请确认所属工单/项目是否在您的责任范围内。</p><h3 id="_2-能否将一条预警同时分配给多人处理" tabindex="-1">2.能否将一条预警同时分配给多人处理？ <a class="header-anchor" href="#_2-能否将一条预警同时分配给多人处理" aria-label="Permalink to &quot;2.能否将一条预警同时分配给多人处理？&quot;">​</a></h3><p>不可以。每条预警仅分配给一名主责任人，以确保责任清晰。如需协作，可在行动项描述中@相关同事，或通过附件上传沟通记录。</p><h3 id="_3-应用负责人能否代替接收人复核" tabindex="-1">3.应用负责人能否代替接收人复核？ <a class="header-anchor" href="#_3-应用负责人能否代替接收人复核" aria-label="Permalink to &quot;3.应用负责人能否代替接收人复核？&quot;">​</a></h3><p>不建议。系统遵循“谁接收、谁复核”原则，确保责任到人。</p><h2 id="处理流程与状态" tabindex="-1">处理流程与状态 <a class="header-anchor" href="#处理流程与状态" aria-label="Permalink to &quot;处理流程与状态&quot;">​</a></h2><h3 id="_1-处理预警时选错了处理方式-还能修改吗" tabindex="-1">1.处理预警时选错了处理方式，还能修改吗？ <a class="header-anchor" href="#_1-处理预警时选错了处理方式-还能修改吗" aria-label="Permalink to &quot;1.处理预警时选错了处理方式，还能修改吗？&quot;">​</a></h3><p>一旦提交，处理方式不可更改。如需调整，请联系应用负责人发起修改流程。</p><h3 id="_2-预警项的状态有哪些-分别代表什么含义" tabindex="-1">2.预警项的状态有哪些？分别代表什么含义？ <a class="header-anchor" href="#_2-预警项的状态有哪些-分别代表什么含义" aria-label="Permalink to &quot;2.预警项的状态有哪些？分别代表什么含义？&quot;">​</a></h3><p>主要状态包括：</p><ul><li><strong>疑似问题</strong>：AI 已识别风险，等待接收人复核</li><li><strong>确认问题</strong>：问题属实，等待处理中</li><li><strong>已关闭</strong>：问题不成立或已解决</li></ul><h3 id="_3-预警项和行动项之间是什么关系" tabindex="-1">3.预警项和行动项之间是什么关系？ <a class="header-anchor" href="#_3-预警项和行动项之间是什么关系" aria-label="Permalink to &quot;3.预警项和行动项之间是什么关系？&quot;">​</a></h3><p>当预警被确认为真实问题且需整改时，可通过“添加行动项”创建具体任务，指派责任人并设定完成时限。行动项独立跟踪闭环，确保问题有效解决。</p><h3 id="_4-ai-误判了正常图片-文档-该如何处理" tabindex="-1">4.AI 误判了正常图片/文档，该如何处理？ <a class="header-anchor" href="#_4-ai-误判了正常图片-文档-该如何处理" aria-label="Permalink to &quot;4.AI 误判了正常图片/文档，该如何处理？&quot;">​</a></h3><p>请选择“补充信息关闭”处理方式，在确认描述中说明实际情况，并可上传佐证材料（如原始文件、沟通记录等），以便后续优化模型。</p><h3 id="_5-系统是否会自动关闭超期未处理的预警" tabindex="-1">5.系统是否会自动关闭超期未处理的预警？ <a class="header-anchor" href="#_5-系统是否会自动关闭超期未处理的预警" aria-label="Permalink to &quot;5.系统是否会自动关闭超期未处理的预警？&quot;">​</a></h3><p>不会。所有预警需人工复核确认。建议定期查看【待确认预警项】，避免遗漏。</p><h3 id="_6-行动项逾期未完成会有什么后果" tabindex="-1">6.行动项逾期未完成会有什么后果？ <a class="header-anchor" href="#_6-行动项逾期未完成会有什么后果" aria-label="Permalink to &quot;6.行动项逾期未完成会有什么后果？&quot;">​</a></h3><p>系统会在首页持续提醒责任人，并可能触发升级机制（如通知上级或合规委员）。</p><h3 id="_7-能否修改已提交的确认描述或附件" tabindex="-1">7.能否修改已提交的确认描述或附件？ <a class="header-anchor" href="#_7-能否修改已提交的确认描述或附件" aria-label="Permalink to &quot;7.能否修改已提交的确认描述或附件？&quot;">​</a></h3><p>不能直接编辑。如确需更正，请联系应用负责人。</p><h2 id="权限与数据管理" tabindex="-1">权限与数据管理 <a class="header-anchor" href="#权限与数据管理" aria-label="Permalink to &quot;权限与数据管理&quot;">​</a></h2><h3 id="_1-如何申请【预警应用中心】的访问权限" tabindex="-1">1.如何申请【预警应用中心】的访问权限？ <a class="header-anchor" href="#_1-如何申请【预警应用中心】的访问权限" aria-label="Permalink to &quot;1.如何申请【预警应用中心】的访问权限？&quot;">​</a></h3><p>请联系系统管理员，并提供您的角色证明（如片区归属、岗位职责等）。</p><h3 id="_2-是否支持批量导出预警或行动项数据" tabindex="-1">2.是否支持批量导出预警或行动项数据？ <a class="header-anchor" href="#_2-是否支持批量导出预警或行动项数据" aria-label="Permalink to &quot;2.是否支持批量导出预警或行动项数据？&quot;">​</a></h3><p>仅应用负责人可在【预警应用中心】→ 对应子应用中导出 Excel 或 CSV 格式数据。预警接收人无此权限。</p><h3 id="_3-附件支持上传哪些文件类型-有大小限制吗" tabindex="-1">3.附件支持上传哪些文件类型？有大小限制吗？ <a class="header-anchor" href="#_3-附件支持上传哪些文件类型-有大小限制吗" aria-label="Permalink to &quot;3.附件支持上传哪些文件类型？有大小限制吗？&quot;">​</a></h3><p>“附件”支持多文件上传（JPG、PNG、PDF、DOCX 等），单文件 ≤20MB。所有提交内容（包括处理方式、描述、附件）均永久留痕，支持审计追溯。</p><h2 id="ai-模型与检测逻辑" tabindex="-1">AI 模型与检测逻辑 <a class="header-anchor" href="#ai-模型与检测逻辑" aria-label="Permalink to &quot;AI 模型与检测逻辑&quot;">​</a></h2><h3 id="_1-图片类中的-ai-cts-和-ai-ctq-有何区别" tabindex="-1">1.图片类中的 “AI-CTS” 和 “AI-CTQ” 有何区别？ <a class="header-anchor" href="#_1-图片类中的-ai-cts-和-ai-ctq-有何区别" aria-label="Permalink to &quot;1.图片类中的 “AI-CTS” 和 “AI-CTQ” 有何区别？&quot;">​</a></h3><ul><li><strong>CTQ</strong>（Critical to Quality）：聚焦产品质量关键点</li><li><strong>CTS</strong>（Critical to Safety）：聚焦人员/环境安全关键点</li></ul><h3 id="_2-为什么有些工步没有触发-ai-检测" tabindex="-1">2.为什么有些工步没有触发 AI 检测？ <a class="header-anchor" href="#_2-为什么有些工步没有触发-ai-检测" aria-label="Permalink to &quot;2.为什么有些工步没有触发 AI 检测？&quot;">​</a></h3><p>AI 检测仅覆盖部分已配置关键控制点（CTQ/CTS）的工步。若某工步未纳入检测范围，请联系业务 AI 项目负责人评估是否需加入监控清单。</p><h3 id="_3-ai-模型多久更新一次-如何反馈误判样本" tabindex="-1">3.AI 模型多久更新一次？如何反馈误判样本？ <a class="header-anchor" href="#_3-ai-模型多久更新一次-如何反馈误判样本" aria-label="Permalink to &quot;3.AI 模型多久更新一次？如何反馈误判样本？&quot;">​</a></h3><p>模型按季度迭代优化。若发现高频误判，请通过“补充信息关闭”提交真实样本及说明，系统将自动归集用于模型训练。</p><h3 id="_4-上传的图片-文档是否会被-ai-用于其他用途" tabindex="-1">4.上传的图片/文档是否会被 AI 用于其他用途？ <a class="header-anchor" href="#_4-上传的图片-文档是否会被-ai-用于其他用途" aria-label="Permalink to &quot;4.上传的图片/文档是否会被 AI 用于其他用途？&quot;">​</a></h3><p>不会。所有数据仅用于当前工单的风险识别与合规闭环，严格遵循公司数据隐私与信息安全政策，不用于外部训练或商业用途。</p><h3 id="_5-一个工单出现多个异常点-会生成多条预警吗" tabindex="-1">5.一个工单出现多个异常点，会生成多条预警吗？ <a class="header-anchor" href="#_5-一个工单出现多个异常点-会生成多条预警吗" aria-label="Permalink to &quot;5.一个工单出现多个异常点，会生成多条预警吗？&quot;">​</a></h3><p>是的。AI 会按异常类型和位置拆分为多条独立预警项，便于逐项确认与处理，避免遗漏。</p><h2 id="系统功能与限制" tabindex="-1">系统功能与限制 <a class="header-anchor" href="#系统功能与限制" aria-label="Permalink to &quot;系统功能与限制&quot;">​</a></h2><h3 id="_1-系统是否支持多语言界面" tabindex="-1">1.系统是否支持多语言界面？ <a class="header-anchor" href="#_1-系统是否支持多语言界面" aria-label="Permalink to &quot;1.系统是否支持多语言界面？&quot;">​</a></h3><p>目前界面语言与用户浏览器或系统设置自动匹配（中/英文）。预警内容（如工步描述、文件名等）保持原始语言不变，以确保准确性。</p>',45)])])}const q=e(o,[["render",l]]);export{_ as __pageData,q as default};
